function swap_bg(e,t){var n=e,o=t,l=document.getElementById("body_bg"),d=document.getElementById("site_bg");l.style.backgroundColor=n,d.setAttribute("src",o)}function show_me(){for(var e=document.getElementsByClassName("hidden"),t=0;t<e.length;t++)e[t].style.display="inline"}function showModal(e){document.getElementById(e).style.display="block"}function closeModal(e){document.getElementById(e).style.display="none"}